import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String input = scanner.next();
        int maxLength = -1, currentLength = 0;
        for (int i = 0; i < n; i++) {
            char ch = input.charAt(i);
            if (ch == '_') {
                if (currentLength > maxLength) maxLength = currentLength;
                currentLength = 0;
            } else if (ch != '(' && ch != ')') {
                currentLength++;
            } else {
                if (currentLength > maxLength) maxLength = currentLength;
                currentLength = 0;
                i++;
                while (i < n && input.charAt(i) != ')') {
                    i++;
                }
            }
        }
        if (currentLength > maxLength) maxLength = currentLength;

        int wordCount = 0, wordLength = 0;
        for (int i = 0; i < n; i++) {
            if (input.charAt(i) == '(') {
                i++;
                while (i < n && input.charAt(i) != ')') {
                    if (input.charAt(i) == '_') {
                        if (wordLength > 0) wordCount++;
                        wordLength = 0;
                    } else if (input.charAt(i) != '_') {
                        wordLength++;
                    }
                    i++;
                }
                if (wordLength > 0) wordCount++;
                wordLength = 0;
            }
        }
        System.out.println(maxLength + " " + wordCount);
    }
}
